/** Tests first/allJavaUNRUN. Public input positive is separate from labelled constructed127
 * Monitor/Item/fault vectors. No private Ready, Frame actor, clock or receipt is fabricated. */
@Isolated class TestCdOriginalTtMonitorGraphWorld extends TestCdOriginalR11LoadingWorld {
 @Test void actualPublicRightMustReturnTheReachedMonitorAndReplayFullCoursePastTheOldBoundary()throws Exception{try(var f=start()){
  for(int n=0;n<238;n++)step(f.loop,8);var r=SessionManager.getCurrentGameplayMode().getRewindRegistry();var full=r.capture();var course=r.captureCourse();for(int n=0;n<2;n++)step(f.loop,8);assertEquals(240,f.module.originalR11EntryFrame().environment().globals().levelFrames());assertFalse(f.module.originalR11EntryFrame().closed());assertTrue(f.placement.pool().state(49).id()==0x19&&f.placement.pool().state(49).subtype()<8&&f.placement.pool().state(49).routine()!=0);var expected=image(f.module);for(boolean c:new boolean[]{false,true}){if(c)r.restoreCourse(course);else r.restore(full);for(int n=0;n<2;n++)step(f.loop,8);CdCapturedValueAssertions.assertCapturedValueEquals(expected,image(f.module));}
 }}
 @Test void constructedMonitorInitUsesItsActualMonitorSourceAndPreservesUnwrittenLayer()throws Exception{try(var f=start()){
  var seed=monitor(f,0);f.placement.pool().write(seed);step(f.loop,0);var s=f.placement.pool().state(127);assertEquals(2,s.routine());assertEquals(0x209CDE,s.longBits(MAPPINGS));assertEquals(0x5A8,s.word(TILE));assertEquals(0x46,s.unsignedByte(COLLISION_TYPE));assertEquals(2,s.unsignedByte(ANIMATION));assertEquals(seed.unsignedByte(LAYER),s.unsignedByte(LAYER));assertEquals(15,s.unsignedByte(WIDTH));
 }}
 @Test void constructedBreakCreatesBothRealChildrenAndReplaysTheirDirtyLifetimePrefix()throws Exception{try(var f=start()){
  f.placement.pool().write(monitor(f,4));var r=SessionManager.getCurrentGameplayMode().getRewindRegistry();var full=r.capture();var course=r.captureCourse();step(f.loop,0);var items=f.placement.pool().capture().slots().stream().filter(s->s.id()==0x1A).toList();var explosions=f.placement.pool().capture().slots().stream().filter(s->s.id()==0x18).toList();assertEquals(1,items.size());assertEquals(1,explosions.size());assertEquals(2,items.getFirst().unsignedByte(ANIMATION));assertEquals(1,explosions.getFirst().unsignedByte(ROUTINE_2));assertEquals(1,explosions.getFirst().subtype());assertEquals(8,f.placement.pool().state(127).routine());assertEquals(1,f.placement.savedFlag(200,1)&1);var expected=image(f.module);for(boolean c:new boolean[]{false,true}){if(c)r.restoreCourse(course);else r.restore(full);step(f.loop,0);CdCapturedValueAssertions.assertCapturedValueEquals(expected,image(f.module));}
 }}
 @Test void constructedMonitorExplosionRunsTheSharedLowPriorityProfileAndDeletesNormally()throws Exception{try(var f=start()){
  f.placement.pool().write(monitor(f,4));step(f.loop,0);int whole=f.placement.pool().capture().slots().stream().filter(s->s.id()==0x18).findFirst().orElseThrow().identity().wholeIndex();step(f.loop,0);var row=f.placement.pool().state(whole);assertEquals(0x680,row.word(TILE));assertEquals(0x21D714,row.longBits(MAPPINGS));assertEquals(2,row.routine());for(int n=0;n<64&&f.placement.pool().state(whole).id()!=0;n++)step(f.loop,0);assertEquals(0,f.placement.pool().state(whole).id());
 }}
 @Test void constructedShieldAwardInitFollowAndCurrentArtReplayOneActualOwner()throws Exception{try(var f=start()){
  awardShield(f);var raw=f.module.originalR11LoadingImage().reserved().slice(5*64,64);assertEquals(3,raw.unsignedByte(0));for(int n=1;n<64;n++)assertEquals(0,raw.unsignedByte(n));assertEquals(1,f.module.originalR11LoadingImage().globals().contact().shield());var before=f.module.originalR11LoadingImage().shieldCpu();var r=SessionManager.getCurrentGameplayMode().getRewindRegistry();var full=r.capture();var course=r.captureCourse();step(f.loop,0);assertEquals(2,f.module.originalR11LoadingImage().reserved().unsignedByte(5*64+0x24));assertEquals(0,f.module.originalR11LoadingPrefix().main().level().powerup());step(f.loop,0);assertEquals(0x82,f.module.originalR11LoadingPrefix().main().level().powerup(),"Native Shield requests art after this row's LoadPowerupArt cut");assertArrayEquals(before.copy(),f.module.originalR11LoadingImage().shieldCpu().copy(),"RunObjects must not replay the earlier art-service cut");step(f.loop,0);assertEquals(2,f.module.originalR11LoadingPrefix().main().level().powerup(),"Next original art service clears bit7 and copies the selected source");var cpu=f.module.originalR11LoadingImage().shieldCpu();assertArrayEquals(f.source.powerupArtSources().copy(0).copy(),cpu.slice(0,1024).copy());assertArrayEquals(before.slice(1024,128).copy(),cpu.slice(1024,128).copy());for(int n=0;n<36;n++)assertArrayEquals(cpu.slice(n*32,32).copy(),com.openggf.game.soniccd.resources.CdR11aCameraArtResidency.readTile(f.module.originalR11LoadingPrefix().section().residency(),0xA880/32+n).copy());var expected=image(f.module);for(boolean c:new boolean[]{false,true}){if(c)r.restoreCourse(course);else r.restore(full);step(f.loop,0);step(f.loop,0);step(f.loop,0);CdCapturedValueAssertions.assertCapturedValueEquals(expected,image(f.module));}
 }}
 @Test void compiledTtShieldOmitsEveryZoneAndLayerReadButKeepsTheCurrentActorReads()throws Exception{try(var f=start()){
  awardShield(f);var shield=(CdShieldPowerup)field(f.binding,"monitorShield");var actual=(CdShieldPowerup.ReadPort)field(shield,"reads");var reads=new ArrayList<CdShieldPowerup.ReadField>();set(shield,"reads",(CdShieldPowerup.ReadPort)x->{reads.add(x);return actual.read(x);});step(f.loop,0);assertTrue(reads.isEmpty(),"Native Init returns without Shield fallthrough");step(f.loop,0);assertEquals(List.of(CdShieldPowerup.ReadField.SHIELD,CdShieldPowerup.ReadField.TIME_WARP,CdShieldPowerup.ReadField.INVINCIBLE,CdShieldPowerup.ReadField.PLAYER_X_WORD,CdShieldPowerup.ReadField.PLAYER_Y_WORD,CdShieldPowerup.ReadField.PLAYER_FLAGS),reads);
 }}
 @Test void landedDestroyFaultRetainsItsOneSoundBeforeAnyChildOrBreakStore()throws Exception{try(var f=start()){
  var seed=monitor(f,4);f.placement.pool().write(seed);var monitor=(CdMonitor)field(f.binding,"monitor");var actual=(CdMonitor.PlayFmCall)field(monitor,"playFm");var failure=new Fault();set(monitor,"playFm",(CdMonitor.PlayFmCall)s->{actual.playFm(s);throw failure;});assertSame(failure,assertThrows(Fault.class,()->step(f.loop,0)));assertEquals(seed,f.placement.pool().state(127));assertFalse(f.placement.pool().capture().slots().stream().anyMatch(s->s.id()==0x1A||s.id()==0x18));assertEquals(0,failure.getSuppressed().length);
 }}
 @Test void idleAndWrongThreadMonitorEntryRejectBeforeItsFirstNativeHeaderStore()throws Exception{try(var f=start()){
  f.placement.pool().write(monitor(f,0));var body=(CdMonitor)field(f.binding,"monitor");var before=f.placement.capture();var frame=f.module.originalR11EntryFrame();var actor=frame.captureActor();var shared=frame.captureShared();assertThrows(IllegalStateException.class,()->body.runPast(127,unreached(),null));var failure=new AtomicReference<Throwable>();var t=new Thread(()->{try{body.runPast(127,unreached(),null);}catch(Throwable e){failure.set(e);}});t.start();t.join(5000);assertFalse(t.isAlive());assertInstanceOf(IllegalStateException.class,failure.get());assertEquals(before.pool().slots(),f.placement.capture().pool().slots());assertArrayEquals(before.savedFlags().copy(),f.placement.capture().savedFlags().copy());assertEquals(actor,frame.captureActor());assertEquals(shared,frame.captureShared());
 }}
 @Test void refusedShieldPublicationKeepsTheAwardIdAndExactThrowable()throws Exception{shieldFault(false);}
 @Test void landedShieldPublicationKeepsItsFirstRoutineByteAndExactThrowable()throws Exception{shieldFault(true);}
 private void shieldFault(boolean landed)throws Exception{try(var f=start()){
  awardShield(f);var body=(CdShieldPowerup)field(f.binding,"monitorShield");var original=(CdShieldPowerup.DispatchObserver)field(body,"observer");var failure=new Fault();set(body,"observer",new CdShieldPowerup.DispatchObserver(){public void beforeOperation(CdShieldPowerup.Call c){if(!landed&&c instanceof CdShieldPowerup.Publication)throw failure;original.beforeOperation(c);}public void afterOperation(CdShieldPowerup.Call c){original.afterOperation(c);if(landed&&c instanceof CdShieldPowerup.Publication)throw failure;}public void failedOperation(CdShieldPowerup.Call c,Throwable e){original.failedOperation(c,e);}});assertSame(failure,assertThrows(Fault.class,()->step(f.loop,0)));var state=(SonicCdGameModule.R11LoadingState)field(f.module,"r11LoadingState");assertEquals(3,state.reserved().unsignedByte(5*64));assertEquals(landed?2:0,state.reserved().unsignedByte(5*64+0x24));assertEquals(0,failure.getSuppressed().length);
 }}
 @Test void unownedItemRewardRetainsItsNativePrefixWithoutAnyInventedAward()throws Exception{try(var f=start()){
  var m=f.module.originalR11EntryFrame().state().motion();var item=f.placement.pool().state(127).moveByte(ID,0x1A).moveByte(ROUTINE,2).moveByte(ANIMATION,5).moveWord(Y_VELOCITY,0).moveWord(X,((m.centreX16_16()>>>16)+96)&65535).moveWord(Y,m.centreY16_16()>>>16);f.placement.pool().write(item);var e=assertThrows(CdMonitorItem.UnsupportedMonitorItem.class,()->step(f.loop,0));assertEquals(CdMonitorItem.UnsupportedBoundary.REWARD_TIME_STOP,e.boundary());assertEquals(127,e.wholeIndex());assertEquals(4,f.placement.pool().state(127).routine());assertEquals(29,f.placement.pool().state(127).word(MONITOR_ITEM_DELETE));var state=(SonicCdGameModule.R11LoadingState)field(f.module,"r11LoadingState");assertEquals(0,state.globals().contact().shield());assertEquals(0,state.reserved().unsignedByte(5*64));
 }}
 private static void awardShield(Fixture f){var m=f.module.originalR11EntryFrame().state().motion();var assets=f.source.timePostAssets();int pointer=assets.mappingsAddress()+(short)assets.visual().mappings().unsignedWord(4)+1;var s=f.placement.pool().state(127).moveByte(ID,0x1A).moveByte(ROUTINE,2).moveByte(ANIMATION,2).moveByte(MAP_FRAME,2).moveByte(SPRITE_FLAGS,0x24).moveByte(PRIORITY,3).moveByte(WIDTH,8).moveWord(TILE,0x85A8).moveWord(X,((m.centreX16_16()>>>16)+96)&65535).moveWord(Y,m.centreY16_16()>>>16).moveWord(Y_VELOCITY,0).moveLong(MAPPINGS,pointer);f.placement.pool().write(s);step(f.loop,0);}
 private static CdObjectState monitor(Fixture f,int routine){var m=f.module.originalR11EntryFrame().state().motion();return f.placement.pool().state(127).moveByte(ID,0x19).moveByte(SUBTYPE,2).moveByte(ROUTINE,routine).moveByte(ANIMATION,2).moveByte(SAVED_FLAGS_ID,200).moveByte(LAYER,0x55).moveByte(SPRITE_FLAGS,4).moveByte(PRIORITY,3).moveByte(WIDTH,15).moveWord(TILE,0x5A8).moveLong(MAPPINGS,0x209CDE).moveWord(X,((m.centreX16_16()>>>16)+96)&65535).moveWord(Y,m.centreY16_16()>>>16);}
 private Fixture start()throws Exception{var source=TestCdOriginalBootPrefix.source();var saves=new SaveManager(root);var profile=CdSaveProfile.fromTemplate(source.initialSaveAssets().orElseThrow()).withPatch(new CdIpxProgress.SavePatch(OptionalInt.of(0x200),OptionalInt.of(4),OptionalInt.of(0x90),OptionalInt.of(0),OptionalInt.of(0x35),OptionalInt.of(2),OptionalInt.of(3)));saves.writeSlot("scd",1,profile.encode());var attempt=SonicCdGameModule.prepareSelectedProfile(source,saves,1,SonicCdGameModule.ProfileEntry.LOAD_GAME,0);var module=attempt.module().orElseThrow();var boot=boot();try{var loop=boot.bootSonicCdSelectedProfile(source,attempt);for(int n=0;n<256&&module.originalR11LoadingPrefix().main().levelStartedByte()!=1;n++)step(loop,0);assertEquals(SonicCdR31aLoadingVisit.Phase.READY,module.originalR11LoadingImage().phase());var binding=field(field(module,"r11World"),"binding");return new Fixture(boot,loop,module,binding,(CdObjectPlacementRuntime)field(binding,"placement"),((CdLevelLoadingSource)field(binding,"ttSource")).objectSource());}catch(Exception|Error e){boot.close();throw e;}}
 private record Fixture(com.openggf.tools.HeadlessGameBoot boot,GameLoop loop,SonicCdGameModule module,Object binding,CdObjectPlacementRuntime placement,CdProgrammeObjectSource source)implements AutoCloseable{public void close(){try{SessionManager.clear();}finally{try{com.openggf.game.GameServices.graphics().cleanup();}finally{boot.close();}}}}
 private static Object image(SonicCdGameModule m){var f=m.originalR11EntryFrame();var p=m.originalR11PlacementImage();return List.of(f.captureActor(),f.captureShared(),p.status(),p.pool().slots(),p.savedFlags(),m.originalR11LoadingPrefix(),m.originalR11LoadingImage(),m.originalR11FirstLoad(),m.originalLoadingWaterImage(),m.originalLoadingWaterPalette(),m.originalR11WorldImage(),m.programServicesState(),m.selectedProfileState());}
 private static CdMonitor.PastGlobals unreached(){return new CdMonitor.PastGlobals(){private int no(){throw new AssertionError("No idle source read");}public int rawTimeZone(){return no();}public int rawTimeWarpDirection(){return no();}public int cameraXWord(){return no();}public int timeAttackMode(){return no();}public int zone(){return no();}public int layer(){return no();}public int timeStopTimer(){return no();}};}
 private static Object field(Object owner,String name)throws Exception{var f=owner.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(owner);}
 private static void set(Object owner,String name,Object value)throws Exception{var f=owner.getClass().getDeclaredField(name);f.setAccessible(true);f.set(owner,value);}
 private static final class Fault extends RuntimeException{}
}
